// src/App.js
import React, { useState, useEffect } from 'react';
import { dynamoDb } from './aws-config';

const App = () => {
  const [contacts, setContacts] = useState([]);
  const [newContact, setNewContact] = useState({ name: '', phone: '', email: '' });
  const [editingContact, setEditingContact] = useState(null);

  // Fetch contacts from DynamoDB when the component loads
  useEffect(() => {
    fetchContacts();
  }, []);

  // Function to fetch contacts
  const fetchContacts = async () => {
    try {
      const params = {
        TableName: 'Contacts',
      };

      const result = await dynamoDb.scan(params).promise();
      setContacts(result.Items || []);
    } catch (error) {
      console.error('Error fetching contacts:', error);
    }
  };

  // Function to create a new contact
  const handleCreateContact = async () => {
    const { name, phone, email } = newContact;
    if (!name || !phone || !email) {
      alert('All fields are required');
      return;
    }

    try {
      const params = {
        TableName: 'Contacts',
        Item: {
          contactId: new Date().getTime().toString(),
          name,
          phone,
          email,
        },
      };

      await dynamoDb.put(params).promise();
      setNewContact({ name: '', phone: '', email: '' }); // Reset form
      fetchContacts(); // Reload contacts
      alert('Contact created successfully');
    } catch (error) {
      console.error('Error creating contact:', error);
    }
  };

  // Function to edit a contact
  const handleEditContact = (index) => {
    const contact = contacts[index];
    setEditingContact(contact);
  };

  // Function to update an existing contact
  const handleUpdateContact = async () => {
    if (!editingContact.name || !editingContact.phone || !editingContact.email) {
      alert('All fields are required');
      return;
    }

    try {
      const params = {
        TableName: 'Contacts',
        Key: {
          contactId: editingContact.contactId,
        },
        UpdateExpression: 'set #name = :name, #phone = :phone, #email = :email',
        ExpressionAttributeNames: {
          '#name': 'name',
          '#phone': 'phone',
          '#email': 'email',
        },
        ExpressionAttributeValues: {
          ':name': editingContact.name,
          ':phone': editingContact.phone,
          ':email': editingContact.email,
        },
      };

      await dynamoDb.update(params).promise();
      fetchContacts(); // Reload contacts
      setEditingContact(null); // Clear editing state
      alert('Contact updated successfully');
    } catch (error) {
      console.error('Error updating contact:', error);
    }
  };

  // Function to delete a contact
  const handleDeleteContact = async (index) => {
    const contact = contacts[index];
    try {
      const params = {
        TableName: 'Contacts',
        Key: {
          contactId: contact.contactId,
        },
      };

      await dynamoDb.delete(params).promise();
      fetchContacts(); // Reload contacts
      alert('Contact deleted successfully');
    } catch (error) {
      console.error('Error deleting contact:', error);
    }
  };

  return (
    <div>
      <h1>Contact Management System</h1>

      <h2>Create Contact</h2>
      <div>
        <input
          type="text"
          placeholder="Name"
          value={newContact.name}
          onChange={(e) => setNewContact({ ...newContact, name: e.target.value })}
        />
        <input
          type="text"
          placeholder="Phone"
          value={newContact.phone}
          onChange={(e) => setNewContact({ ...newContact, phone: e.target.value })}
        />
        <input
          type="email"
          placeholder="Email"
          value={newContact.email}
          onChange={(e) => setNewContact({ ...newContact, email: e.target.value })}
        />
        <button onClick={handleCreateContact}>Create</button>
      </div>

      {editingContact && (
        <div>
          <h2>Edit Contact</h2>
          <input
            type="text"
            value={editingContact.name}
            onChange={(e) => setEditingContact({ ...editingContact, name: e.target.value })}
          />
          <input
            type="text"
            value={editingContact.phone}
            onChange={(e) => setEditingContact({ ...editingContact, phone: e.target.value })}
          />
          <input
            type="email"
            value={editingContact.email}
            onChange={(e) => setEditingContact({ ...editingContact, email: e.target.value })}
          />
          <button onClick={handleUpdateContact}>Update</button>
          <button onClick={() => setEditingContact(null)}>Cancel</button>
        </div>
      )}

      <h2>Contacts List</h2>
      <ul>
        {contacts.map((contact, index) => (
          <li key={contact.contactId}>
            {contact.name} - {contact.phone} - {contact.email}
            <button onClick={() => handleEditContact(index)}>Edit</button>
            <button onClick={() => handleDeleteContact(index)}>Delete</button>
          </li>
        ))}
      </ul>
    </div>
  );
};

export default App;
